-- LEGIT Weddings launch slice (applied live via migration legit_weddings_slice). Georgia is the only enabled state.
create table if not exists legit_wedding_packages (key text primary key, title text not null, price_cents bigint not null check (price_cents > 0), summary text not null default '', includes jsonb not null default '[]', excludes jsonb not null default '[]', guest_limit int not null default 100, payment_schedule text not null default '', cancellation text not null default '', active boolean not null default true, sort int not null default 0, updated_at timestamptz not null default now());
create table if not exists legit_wedding_areas (state text primary key check (char_length(state)=2), name text not null, enabled boolean not null default false, note text not null default '', updated_at timestamptz not null default now());
create table if not exists legit_wedding_requests (id uuid primary key default gen_random_uuid(), user_id uuid references legit_users(id) on delete set null, package_key text references legit_wedding_packages(key), name text not null, email text not null, phone text, event_date date, guest_count int, venue_name text, venue_city text, venue_state text not null, venue_zip text, vision text, budget_note text, status text not null default 'requested' check (status in ('requested','reviewing','proposal_sent','declined','closed')), staff_note text, ip_hash text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists legit_wedding_requests_status on legit_wedding_requests(status, created_at desc);
alter table legit_wedding_packages enable row level security; alter table legit_wedding_areas enable row level security; alter table legit_wedding_requests enable row level security;
insert into legit_wedding_areas(state,name,enabled,note) values ('GA','Georgia',true,'Launch state') on conflict do nothing;
